const raw = $input.first().json.content?.parts?.[0]?.text ?? $input.first().json.text ?? '';
const cleaned = raw.replace(/```json|```/g, '').trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch (e) {
  result = {
    claim_id: $('Input').first().json.claim_id,
    error: true,
    error_message: 'Réponse du modèle non valide : ' + e.message,
    raw_response: raw
  };
}
return [{ json: result }];
